$(
=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=
  Congruence
=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=
$)

  ${
    tkgeom.p $e |- P = ( Base ` G ) $.
    tkgeom.d $e |- .- = ( dist ` G ) $.
    tkgeom.i $e |- I = ( Itv ` G ) $.
    tkgeom.g $e |- ( ph -> G e. TarskiG ) $.

    ${
      tgcgrcomimp.a $e |- ( ph -> A e. P ) $.
      tgcgrcomimp.b $e |- ( ph -> B e. P ) $.
      tgcgrcomimp.c $e |- ( ph -> C e. P ) $.
      tgcgrcomimp.d $e |- ( ph -> D e. P ) $.
      $( Congruence commutes on the RHS. Theorem 2.5 of [Schwabhauser] p. 27.
         (Contributed by David A. Wheeler, 29-Jun-2020.) $)
      tgcgrcomimp $p |- ( ph ->
        ( ( A .- B ) = ( C .- D ) -> ( A .- B ) = ( D .- C ) ) ) $=
        ( co wceq axtgcgrrflx eqeq2d biimpd ) ABCIRZDEIRZSUCEDIRZSAUDUEUCAFGHID
        EJKLMPQTUAUB $.
    $}

    ${
      tgcgrcomr.a $e |- ( ph -> A e. P ) $.
      tgcgrcomr.b $e |- ( ph -> B e. P ) $.
      tgcgrcomr.c $e |- ( ph -> C e. P ) $.
      tgcgrcomr.d $e |- ( ph -> D e. P ) $.
      tgcgrcomr.6 $e |- ( ph -> ( A .- B ) = ( C .- D ) ) $.
      $( Congruence commutes on the RHS. Variant of Theorem 2.5 of
         [Schwabhauser] p. 27, but in a convenient form for a common case.
         (Contributed by David A. Wheeler, 29-Jun-2020.) $)
      tgcgrcomr $p |- ( ph -> ( A .- B ) = ( D .- C ) ) $=
        ( co axtgcgrrflx eqtrd ) ABCISDEISEDISRAFGHIDEJKLMPQTUA $.

      $( Congruence commutes on the LHS. Variant of Theorem 2.5 of
         [Schwabhauser] p. 27, but in a convenient form for a common case.
         (Contributed by David A. Wheeler, 29-Jun-2020.) $)
      tgcgrcoml $p |- ( ph -> ( B .- A ) = ( C .- D ) ) $=
        ( co axtgcgrrflx eqtr3d ) ABCISCBISDEISAFGHIBCJKLMNOTRUA $.
    $}

    ${
