      tgcgrcomlr.d $e |- ( ph -> D e. P ) $.
      tgcgrcomlr.6 $e |- ( ph -> ( A .- B ) = ( C .- D ) ) $.
      $( Congruence commutes on both sides.  (Contributed by Thierry Arnoux,
         23-Mar-2019.) $)
      tgcgrcomlr $p |- ( ph -> ( B .- A ) = ( D .- C ) ) $=
        ( co axtgcgrrflx 3eqtr3d ) ABCISDEISCBISEDISRAFGHIBCJKLMNOTAFGHIDEJKLMP
        QTUA $.

      $( Congruence and equality.  (Contributed by Thierry Arnoux,
         27-Aug-2019.) $)
      tgcgreqb $p |- ( ph -> ( A = B <-> C = D ) ) $=
        ( wcel adantr wa cstrkg co simpr oveq1d eqtr3d axtgcgrid eqtrd impbida
        wceq ) ABCUJZDEUJZAUKUAZFGHIDECJKLAGUBSZUKMTADFSUKPTAEFSZUKQTACFSZUKOTU
