        BFSULNTAUPULOTAUOULQTUTUQUREEIUCAUSULRTUTDEEIAULUDUEUHUGUI $.

      ${
        tgcgreq.1 $e |- ( ph -> A = B ) $.
        $( Congruence and equality.  (Contributed by Thierry Arnoux,
           27-Aug-2019.) $)
        tgcgreq $p |- ( ph -> C = D ) $=
          ( wceq tgcgreqb mpbid ) ABCTDETSABCDEFGHIJKLMNOPQRUAUB $.
      $}

      ${
        tgcgrneq.1 $e |- ( ph -> A =/= B ) $.
        $( Congruence and equality.  (Contributed by Thierry Arnoux,
           27-Aug-2019.) $)
        tgcgrneq $p |- ( ph -> C =/= D ) $=
          ( wne tgcgreqb necon3bid mpbid ) ABCTDETSABCDEABCDEFGHIJKLMNOPQRUAUBU
          C $.
      $}
    $}

    ${
      $d x .- $.  $d x A $.  $d x B $.  $d x I $.  $d x P $.  $d x ph $.
