    motcgr3.a $e |- ( ph -> A e. P ) $.
    motcgr3.b $e |- ( ph -> B e. P ) $.
    motcgr3.c $e |- ( ph -> C e. P ) $.
    motcgr3.d $e |- ( ph -> D = ( H ` A ) ) $.
