    ${
      iseqlgd.1 $e |- ( ph -> ( A .- B ) = ( B .- C ) ) $.
      iseqlgd.2 $e |- ( ph -> ( B .- C ) = ( C .- A ) ) $.
      iseqlgd.3 $e |- ( ph -> ( C .- A ) = ( A .- B ) ) $.
