      ( P : ( 1 ... N ) -1-1-> ( EE ` N ) /\ A e. ( EE ` N ) ) /\
      ( B e. ( EE ` N ) /\ C e. ( EE ` N ) ) ) ->
      ( A. i e. ( 2 ... N ) ( <. ( P ` 1 ) , A >. Cgr <. ( P ` i ) , A >. /\
           <. ( P ` 1 ) , B >. Cgr <. ( P ` i ) , B >. /\
           <. ( P ` 1 ) , C >. Cgr <. ( P ` i ) , C >. ) ->
        ( A Btwn <. B , C >. \/ B Btwn <. C , A >. \/
          C Btwn <. A , B >. ) ) ) @= ? @.
